// WorkspaceAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func WorkspaceAuditing(policy WorkspaceAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Workspace]()
		if err != nil {
			return err
		}
		return RegisterWorkspaceObserver(registrar, pool, NewWorkspaceObserver(name), func(resolver foundation.Resolver) (func() WorkspaceHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() WorkspaceHooks {
				write := func(ctx context.Context, tx *database.Tx, changes WorkspaceChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return WorkspaceHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
